  /**
   * Configures client certificate for mTLS using X509CertChain. chain[0] is the leaf cert, followed
   * by intermediates.
   */
  private KeyManager[] configureClientCertificate(X509CertChain certChain) throws Exception {
    CertificateFactory cf = CertificateFactory.getInstance("X.509");

    // Parse all chain certs
    Certificate[] certs = new Certificate[certChain.getChainCount()];
    for (int i = 0; i < certChain.getChainCount(); i++) {
      byte[] certBytes = Utils.decodeBase64(certChain.getChain(i).getBase64());
      certs[i] = cf.generateCertificate(new ByteArrayInputStream(certBytes));
    }

    // Parse private key from chain's key field
    byte[] keyBytes = Utils.decodeBase64(certChain.getKey().getBase64());
    PKCS8EncodedKeySpec keySpec = new PKCS8EncodedKeySpec(keyBytes);
    // Try Ed25519 first, fall back to RSA
    java.security.PrivateKey privateKey;
    try {
      KeyFactory kf = KeyFactory.getInstance("Ed25519");
      privateKey = kf.generatePrivate(keySpec);
    } catch (Exception e) {
      KeyFactory kf = KeyFactory.getInstance("RSA");
      privateKey = kf.generatePrivate(keySpec);
    }

    // Create keystore with the certificate chain and key
    KeyStore keyStore = KeyStore.getInstance(KeyStore.getDefaultType());
    keyStore.load(null, null);
    keyStore.setKeyEntry("client", privateKey, new char[0], certs);

    // Create key manager
    KeyManagerFactory kmf = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
    kmf.init(keyStore, new char[0]);

    return kmf.getKeyManagers();
  }

  /** Configures root certificates for server verification. */
